mkdir -p "$TMPDIR/probe" && cat > "$TMPDIR/probe/Probe.java" <<'EOF'
import org.apache.commons.lang3.time.DurationFormatUtils;

public class Probe {
    public static void main(String[] args) throws Exception {
        System.out.println("ISO 1000ms: [" + DurationFormatUtils.formatDurationISO(1000) + "]");
        System.out.println("ISO 1 day: [" + DurationFormatUtils.formatDurationISO(86400000L) + "]");
        System.out.println("ISO full: [" + DurationFormatUtils.formatDurationISO(86400000L+6*3600000L+5*60000L+4321) + "]");
        System.out.println("words 0,true,true: [" + DurationFormatUtils.formatDurationWords(0, true, true) + "]");
        System.out.println("words 0,false,false: [" + DurationFormatUtils.formatDurationWords(0, false, false) + "]");
        System.out.println("words 1 day,false,false: [" + DurationFormatUtils.formatDurationWords(86400000L, false, false) + "]");
        System.out.println("words 1h1m1s,false,false: [" + DurationFormatUtils.formatDurationWords(3600000L+60000L+1000L, false, false) + "]");
        System.out.println("words 1h,true,true: [" + DurationFormatUtils.formatDurationWords(3600000L, true, true) + "]");
        System.out.println("HMS 0: [" + DurationFormatUtils.formatDurationHMS(0) + "]");
        System.out.println("HMS 1: [" + DurationFormatUtils.formatDurationHMS(1) + "]");
        try {
            DurationFormatUtils.formatDuration(-1, "HH:mm:ss");
            System.out.println("no exception for negative!");
        } catch (IllegalArgumentException e) {
            System.out.println("negative threw IAE: " + e.getMessage());
        }
        try {
            DurationFormatUtils.formatPeriod(5, 1, "d");
            System.out.println("no exception for start>end!");
        } catch (IllegalArgumentException e) {
            System.out.println("start>end threw IAE: " + e.getMessage());
        }
        // optional bracket examples
        System.out.println("opt1 1day: [" + DurationFormatUtils.formatDuration(86400000L, "d'd'[H'h'm'm']s's'", false) + "]");
        System.out.println("opt1 1hour: [" + DurationFormatUtils.formatDuration(3600000L, "d'd'[H'h'm'm']s's'", false) + "]");
        System.out.println("opt1 1min: [" + DurationFormatUtils.formatDuration(60000L, "d'd'[H'h'm'm']s's'", false) + "]");
        System.out.println("opt1 zero: [" + DurationFormatUtils.formatDuration(0, "d'd'[H'h'm'm']s's'", false) + "]");

        System.out.println("opt2 1day: [" + DurationFormatUtils.formatDuration(86400000L, "[d'd'H'h'm'm']s's'", false) + "]");
        System.out.println("opt2 1hour: [" + DurationFormatUtils.formatDuration(3600000L, "[d'd'H'h'm'm']s's'", false) + "]");
        System.out.println("opt2 1min: [" + DurationFormatUtils.formatDuration(60000L, "[d'd'H'h'm'm']s's'", false) + "]");
        System.out.println("opt2 zero: [" + DurationFormatUtils.formatDuration(0, "[d'd'H'h'm'm']s's'", false) + "]");

        System.out.println("opt3 1day: [" + DurationFormatUtils.formatDuration(86400000L, "[d'd'H'h'm'm's's']", false) + "]");
        System.out.println("opt3 1hour: [" + DurationFormatUtils.formatDuration(3600000L, "[d'd'H'h'm'm's's']", false) + "]");
        System.out.println("opt3 1min: [" + DurationFormatUtils.formatDuration(60000L, "[d'd'H'h'm'm's's']", false) + "]");
        System.out.println("opt3 zero: [" + DurationFormatUtils.formatDuration(0, "[d'd'H'h'm'm's's']", false) + "]");

        System.out.println("opt4 1day: [" + DurationFormatUtils.formatDuration(86400000L, "['{'d'}']HH':'mm", true) + "]");
        System.out.println("opt4 1hour: [" + DurationFormatUtils.formatDuration(3600000L, "['{'d'}']HH':'mm", true) + "]");
        System.out.println("opt4 1min: [" + DurationFormatUtils.formatDuration(60000L, "['{'d'}']HH':'mm", true) + "]");
        System.out.println("opt4 zero: [" + DurationFormatUtils.formatDuration(0, "['{'d'}']HH':'mm", true) + "]");

        System.out.println("opt5 1day: [" + DurationFormatUtils.formatDuration(86400000L, "[dHms]", false) + "]");
        System.out.println("opt5 1hour: [" + DurationFormatUtils.formatDuration(3600000L, "[dHms]", false) + "]");
        System.out.println("opt5 1min: [" + DurationFormatUtils.formatDuration(60000L, "[dHms]", false) + "]");
        System.out.println("opt5 zero: [" + DurationFormatUtils.formatDuration(0, "[dHms]", false) + "]");

        try {
            DurationFormatUtils.formatDuration(0, "[d[H]]");
            System.out.println("no exception nested optional!");
        } catch (IllegalArgumentException e) {
            System.out.println("nested optional threw: " + e.getMessage());
        }
        try {
            DurationFormatUtils.formatDuration(0, "d]");
            System.out.println("no exception unopened close!");
        } catch (IllegalArgumentException e) {
            System.out.println("unopened close threw: " + e.getMessage());
        }
        try {
            DurationFormatUtils.formatDuration(0, "[d");
            System.out.println("no exception unmatched optional!");
        } catch (IllegalArgumentException e) {
            System.out.println("unmatched optional threw: " + e.getMessage());
        }
        try {
            DurationFormatUtils.formatDuration(0, "d'abc");
            System.out.println("no exception unmatched quote!");
        } catch (IllegalArgumentException e) {
            System.out.println("unmatched quote threw: " + e.getMessage());
        }
    }
}
